  TERAVOLT = { abilityId = 164, behaviour = { chance = 100, effects = { { kind = "other", what = "this Pokémon's moves ignore the target's ability whenever that ability would hinder or prevent the move's effect" } }, expressible = false, notes = "Detailed rules on which abilities are ignored (hindering/preventing abilities like Water Absorb, Clear Body, Thick Fat) versus which aren't (Cursed Body, Liquid Ooze, Multitype, type/forme-change abilities like Color Change, effects no longer tied to an ability such as Drizzle's rain) are not representable as a single effect.", scope = "self", trigger = "passive" }, effect = "This Pokémon's moves completely ignore abilities that could hinder or prevent their effect on the target. For example, this Pokémon's moves ignore abilities that would fully negate them, such as Water Absorb; abilities that would prevent any of their effects, such as Clear Body, Shell Armor, or Sticky Hold; and abilities that grant any general protective benefit, such as Simple, Snow Cloak, or Thick Fat. If an ability could either hinder or help this Pokémon's moves, e.g. Dry Skin or Unaware, the ability is ignored either way. Abilities that do not fit this description, even if they could hinder moves in some other way, are not affected. For example, Cursed Body only affects potential future uses of the move, while Liquid Ooze and Shadow Tag can only hinder a move's effect on the user. This ablity cannot ignore type or form changes granted by abilities, for example Color Change or Forecast; nor effects that were caused by abilities but are no longer tied to an ability, such as the rain from Drizzle. This ability cannot ignore Multitype at all. An ability ignored by this ability is only nullified while the move is being used. For example, this Pokémon's moves can paralyze a Pokémon with Limber, but Limber will activate and heal the paralysis immediately thereafter, and this Pokémon's Spikes are not affected by this ability after they have been placed. When this Pokémon enters battle, all participating trainers are notified that it has this ability. This ability functions identically to Mold Breaker and Turboblaze.", effectChanges = {}, generation = "generation-v", id = "TERAVOLT", name = "Teravolt", shortEffect = "Bypasses targets' abilities if they could hinder or prevent moves.", slug = "teravolt", speciesCount = 2 },
