  TRUANT = { abilityId = 54, behaviour = { chance = 100, effects = { { kind = "other", what = "loafs around (does nothing) every second turn it would otherwise act" } }, expressible = false, notes = "Interaction with recharge/preparation-turn moves, multi-turn forced moves, confusion, sleep/freeze, and failed-move turns is too intricate for the effects list; see full text.", scope = "self", trigger = "turn_start" }, effect = "Every second turn on which this Pokémon should attempt to use a move, it will instead do nothing (\"loaf around\"). Loafing around interrupts moves that take multiple turns the same way paralysis, flinching, etc do. Most such moves, for example Bide or Rollout, are simply cut off upon loafing around. Attacks with a recharge turn, such as Hyper Beam, do not have to recharge; attacks with a preparation turn, such as Fly, do not end up being used. Moves that are forced over multiple turns and keep going through failure, such as Outrage, Uproar, or any move forced by Encore, keep going as usual. If this Pokémon is confused, its confusion is not checked when loafing around; the Pokémon cannot hurt itself, and its confusion does not end or come closer to ending. If this Pokémon attempts to move but fails, e.g. because of paralysis or Gravity, it still counts as having moved and will loaf around the next turn. If it does not attempt to move, e.g. because it is asleep or frozen, whatever it would have done will be postponed until its next attempt; that is, it will either loaf around or move as usual, depending on what it last did. This ability cannot be changed with Worry Seed, but it can be disabled with Gastro Acid, changed with Role Play, or traded away with Skill Swap.", effectChanges = {}, generation = "generation-iii", id = "TRUANT", name = "Truant", shortEffect = "Skips every second turn.", slug = "truant", speciesCount = 3 },
